const ORANGE_HRM = "https://opensource-demo.orangehrmlive.com/web/index.php";
const { browser, page } = await launch();

await page.goto(ORANGE_HRM + "/auth/login");
await page.getByPlaceholder("Username").fill("Admin");
await page.getByPlaceholder("Password").fill("admin123");
await page.getByRole("button", { name: "Login" }).click();
await page.waitForURL("**/dashboard/index");

const base = "Verify" + Math.floor(Math.random() * 100000);

await page.goto(ORANGE_HRM + "/pim/addEmployee");
await page.getByPlaceholder("First Name").fill("Temp");
await page.getByPlaceholder("Last Name").fill(base);
await page.getByRole("button", { name: "Save" }).click();
await page.waitForLoadState("networkidle");

async function findRow(name) {
  await page.goto(ORANGE_HRM + "/pim/viewEmployeeList");
  await page.getByPlaceholder("Type for hints...").first().fill(name);
  await page.getByRole("button", { name: "Search" }).click();
  await page.waitForLoadState("networkidle");
  return page.locator(
    "xpath=//div[text()='" + name + "']/parent::div/following-sibling::div[last()]",
  );
}

async function rename(from, to) {
  const cell = await findRow(from);
  await cell.locator("i.bi-pencil-fill").click();
  await page.waitForLoadState("networkidle");
  const lastNameBox = page.getByPlaceholder("Last Name");
  await lastNameBox.fill(to);
  await page.getByRole("button", { name: "Save" }).click();
  await page.waitForLoadState("networkidle");

  // The toast can fire BEFORE the save lands. Reload and check; save again if needed.
  const check = await findRow(to);
  if ((await check.count()) === 0) {
    console.log("save had not landed - retrying", to);
    await rename(from, to);
  }
  console.log("confirmed:", to);
}

await rename(base, base + "Round1");
await rename(base + "Round1", base + "Round2");

const finalCell = await findRow(base + "Round2");
await finalCell.locator("i.bi-trash").click();
await page.getByRole("button", { name: "Yes, Delete" }).click();

await show(page);
await browser.close();
```

**The lesson hiding in the verify-after-save step.** This sandbox shows "Successfully Updated" a beat before the write has actually landed. A test that trusts the toast passes on a save that has not happened, and then the *second* rename fails while searching for a name that does not exist yet — a failure that points at the wrong line entirely.

Reloading and searching for the new value is the only honest confirmation: it asks the server what it stored rather than believing what the UI said.

**This is the difference between waiting for an element and waiting for an outcome.** Playwright's auto-waiting handles the first for free. The second is your job.

