import { type Page, expect } from "@playwright/test";

const ORANGE_HRM = "https://opensource-demo.orangehrmlive.com/web/index.php";

export async function updateLastName(
  page: Page,
  oldLastName: string,
  newLastName: string,
): Promise<void> {
  const actionsCell = await findEmployeeRow(page, oldLastName);
  await actionsCell.locator("i.bi-pencil-fill").click();
  await page.waitForLoadState("networkidle");

  await page.getByPlaceholder("Last Name").fill(newLastName);
  await page.getByRole("button", { name: "Save" }).click();
  await page.waitForLoadState("networkidle");

  // Confirm against the server, not against the toast - see Day 4.2.
  await page.goto(ORANGE_HRM + "/pim/viewEmployeeList");
  await page.getByPlaceholder("Type for hints...").first().fill(newLastName);
  await page.getByRole("button", { name: "Search" }).click();
  await page.waitForLoadState("networkidle");

  await expect(
    page.locator("xpath=//div[text()='" + newLastName + "']"),
  ).toHaveCount(1);
}
```

And a spec that uses it end to end:

```ts
import { test } from "@playwright/test";
import { signIn, createEmployee, updateLastName, deleteEmployee } from "./employee-list-helpers";

test("an employee can be renamed and the change persists", async ({ page }) => {
  const original = "Verify" + Math.floor(Math.random() * 100000);
  const renamed = original + "Renamed";

  await signIn(page);
  await createEmployee(page, "Temp", original);
  await updateLastName(page, original, renamed);
  await deleteEmployee(page, renamed);
});
```

**Read the spec on its own.** It is four English sentences: sign in, create, rename, delete. No XPath, no `waitForLoadState`, no knowledge of which icon class is the pencil. All of that lives in one file, so when OrangeHRM changes its markup exactly one file changes.

**Why the confirmation belongs inside the helper.** Every caller needs it and every caller would forget it. A helper called `updateLastName` that returns before the update has landed is lying about its own name — and the bug it causes surfaces two steps later, somewhere else entirely.

> `employee-list-helpers.ts`, not `.spec.ts`. The runner collects anything with the spec suffix.
